const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// The spine. Kept deliberately thin here so M1 (the deal wizard) extends these\n// rather than migrating away from them.\n// ---------------------------------------------------------------------------\n\nenum StakeholderKind {\n  INDIVIDUAL\n  ENTITY\n}\n\nmodel Stakeholder {\n  id         String          @id @default(cuid())\n  kind       StakeholderKind @default(INDIVIDUAL)\n  name       String\n  idNumber   String?\n  /// Stored lowercase. Unique because sign-in links a login to the one row holding its\n  /// verified address, so a second row for the same person is a deal they never see.\n  email      String?         @unique\n  phone      String?\n  /// Supabase auth user id, set when someone signs in and claims this stakeholder.\n  /// Most stakeholders (landlords, tenants) never sign in and leave this null; it is\n  /// what separates \"a person on a deal\" from \"a person with a login\".\n  authUserId String?         @unique\n  /// Agents on one team work each other's deals as if each were the deal's agent.\n  teamId     String?\n  createdAt  DateTime        @default(now())\n  updatedAt  DateTime        @updatedAt\n\n  team Team? @relation(fields: [teamId], references: [id], onDelete: SetNull)\n\n  tenanciesAsLandlord         Tenancy[]                 @relation(\"LandlordTenancies\")\n  tenanciesAsTenant           Tenancy[]                 @relation(\"TenantTenancies\")\n  tenanciesAsAgent            Tenancy[]                 @relation(\"AgentTenancies\")\n  inspectionsRun              Inspection[]\n  signatures                  Signature[]\n  deletionRequests            AccountDeletionRequest[]\n  maintenanceCasesReported    MaintenanceCase[]         @relation(\"MaintenanceReporter\")\n  maintenanceEvents           MaintenanceEvent[]\n  maintenanceVerifications    MaintenanceVerification[]\n  maintenanceEvidenceUploaded MaintenanceEvidence[]\n  responsibilityProposed      ResponsibilityProposal[]  @relation(\"ResponsibilityProposer\")\n  responsibilityResponded     ResponsibilityProposal[]  @relation(\"ResponsibilityResponder\")\n  notifications               Notification[]\n  deviceInstallations         DeviceInstallation[]\n  branding                    AgentBranding?\n  errorEvents                 ErrorEvent[]\n  /// The plan of an agent who is on no team. An agent on a team uses the team's.\n  subscription                Subscription?             @relation(\"OwnSubscription\")\n  subscriptionsManaged        Subscription[]            @relation(\"ManagedSubscriptions\")\n\n  @@index([name])\n  @@index([teamId])\n}\n\n/// A small group of agents who share their deals. Set up with `pnpm team:set`; nothing in\n/// the app creates or edits one yet. Leaving ends access to teammates' deals at once, and\n/// a deal never moves: it stays with the agent who holds it.\nmodel Team {\n  id        String   @id @default(cuid())\n  name      String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  members      Stakeholder[]\n  subscription Subscription?\n}\n\nenum Plan {\n  PRO\n}\n\n/// A workspace's paid or comped plan. A workspace is a team, or an agent on no team, so\n/// exactly one of teamId and stakeholderId is set (a CHECK constraint holds it). Free is\n/// the absence of a row. What a plan allows is decided in `src/lib/plan.ts` and nowhere\n/// else; this row only records what was bought.\nmodel Subscription {\n  id                   String    @id @default(cuid())\n  teamId               String?   @unique\n  stakeholderId        String?   @unique\n  plan                 Plan\n  seats                Int\n  /// Stripe's subscription status verbatim (active, trialing, past_due, canceled, ...),\n  /// or \"comped\" for a plan set by `pnpm plan:set` with nothing in Stripe behind it.\n  status               String\n  stripeCustomerId     String?   @unique\n  stripeSubscriptionId String?   @unique\n  currentPeriodEnd     DateTime?\n  cancelAtPeriodEnd    Boolean   @default(false)\n  /// The member who manages billing. Null once they delete their account, and then any\n  /// member of the workspace may.\n  managedById          String?\n  createdAt            DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n\n  team        Team?        @relation(fields: [teamId], references: [id], onDelete: Cascade)\n  stakeholder Stakeholder? @relation(\"OwnSubscription\", fields: [stakeholderId], references: [id], onDelete: Cascade)\n  managedBy   Stakeholder? @relation(\"ManagedSubscriptions\", fields: [managedById], references: [id], onDelete: SetNull)\n}\n\n/// How an agent's reports are headed: agency name, licence numbers, contact, logo. One\n/// per agent, because a Singapore agent is individually registered and a report is\n/// prepared by one. With none set, a report reads as Kivilo's. The header is\n/// presentation, not part of what the parties signed, so it follows the agent's current\n/// branding rather than being frozen with the report.\nmodel AgentBranding {\n  stakeholderId   String   @id\n  agencyName      String\n  agencyLicence   String?\n  ceaRegistration String?\n  phone           String?\n  /// Private bucket path, at `branding/<stakeholderId>/logo`.\n  logoPath        String?\n  updatedAt       DateTime @updatedAt\n\n  stakeholder Stakeholder @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n}\n\nenum PropertyType {\n  HDB\n  PRIVATE_NON_LANDED\n  LANDED\n  COMMERCIAL\n}\n\n/// The durable hub. Outlives every relationship on it.\nmodel Property {\n  id         String       @id @default(cuid())\n  line1      String\n  unit       String?\n  postalCode String\n  type       PropertyType\n  createdAt  DateTime     @default(now())\n  updatedAt  DateTime     @updatedAt\n\n  tenancies Tenancy[]\n  assets    PropertyAsset[]\n\n  @@index([postalCode])\n}\n\nmodel Tenancy {\n  id                 String   @id @default(cuid())\n  propertyId         String\n  landlordId         String\n  tenantId           String\n  agentId            String?\n  startDate          DateTime\n  endDate            DateTime\n  monthlyRent        Decimal  @db.Decimal(10, 2)\n  deposit            Decimal  @db.Decimal(10, 2)\n  /// Tenant pays up to this per repair, landlord the rest. Only prefills a cost\n  /// proposal; the tenant still accepts or rejects every one.\n  minorRepairCap     Decimal? @db.Decimal(10, 2)\n  /// Whether the agent may accept or reject a tenant's cost proposal for the landlord.\n  /// Only the landlord can change it.\n  agentMayAgreeCosts Boolean  @default(true)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  property Property     @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  landlord Stakeholder  @relation(\"LandlordTenancies\", fields: [landlordId], references: [id])\n  tenant   Stakeholder  @relation(\"TenantTenancies\", fields: [tenantId], references: [id])\n  agent    Stakeholder? @relation(\"AgentTenancies\", fields: [agentId], references: [id])\n\n  inspections      Inspection[]\n  maintenanceCases MaintenanceCase[]\n\n  @@index([propertyId])\n}\n\n// ---------------------------------------------------------------------------\n// M4: check-in / check-out\n// ---------------------------------------------------------------------------\n\nenum InspectionKind {\n  CHECK_IN\n  CHECK_OUT\n}\n\nenum InspectionStatus {\n  DRAFT\n  CAPTURING\n  PROCESSING\n  REVIEW\n  AWAITING_SIGNATURE\n  COMPLETED\n  FAILED\n}\n\nmodel Inspection {\n  id              String           @id @default(cuid())\n  tenancyId       String\n  kind            InspectionKind\n  status          InspectionStatus @default(DRAFT)\n  conductedById   String?\n  conductedAt     DateTime?\n  /// A check-out points at the check-in it is measured against.\n  baselineId      String?          @unique\n  summary         String?\n  processingError String?\n  /// Unguessable bearer token for the read-only report link handed to the landlord\n  /// and tenant. Null until someone shares the report. Revoked by setting it back to\n  /// null, which is why it is nullable rather than generated with the row.\n  shareToken      String?          @unique\n  sharedAt        DateTime?\n  /// Consent by the inspector before home media is sent to external AI providers.\n  aiConsentAt     DateTime?\n  aiConsentById   String?\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  tenancy     Tenancy      @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  conductedBy Stakeholder? @relation(fields: [conductedById], references: [id])\n  baseline    Inspection?  @relation(\"Baseline\", fields: [baselineId], references: [id])\n  checkOut    Inspection?  @relation(\"Baseline\")\n\n  rooms       Room[]\n  findings    Finding[]\n  signatures  Signature[]\n  assessments AssessmentVersion[]\n\n  @@index([tenancyId, kind])\n}\n\nenum CaptureKind {\n  /// Narrated walkthrough of one room.\n  VIDEO\n  /// Deliberate still: a label, a serial plate, a meter face, a specific defect.\n  /// Video is downsampled too far to read small print; this is what OCR runs on.\n  PHOTO\n}\n\n/// The evidence. AI is the scribe; this is the witness.\n/// Captures belong to a room, not to the inspection, so an inspector can re-shoot\n/// one room without disturbing rooms already reviewed.\nmodel Capture {\n  id             String      @id @default(cuid())\n  /// Stable native-client id. A lost registration response must not create another row.\n  clientId       String?     @unique\n  roomId         String\n  kind           CaptureKind @default(VIDEO)\n  storagePath    String      @unique\n  mimeType       String\n  sizeBytes      Int\n  durationSec    Int?\n  /// What the inspector said while recording, or typed against a photo.\n  transcript     String?\n  /// Inspector's own note attached at capture time, before any model sees it.\n  note           String?\n  /// Rings and arrows the inspector drew over this photo, with the intrinsic size of\n  /// the upright image they were drawn against. Data over an unmodified original: the\n  /// object at storagePath is never rewritten. Shape and parser live in\n  /// src/lib/annotations.ts. Human-authored by construction, so it carries its own\n  /// author and time and never a confidence.\n  annotations    Json?\n  processedAt    DateTime?\n  /// A still from a video, stored next to it, so a list can show what a video is without\n  /// loading any of it. Made by the poster cron (src/lib/poster.ts); null until then.\n  posterPath     String?     @unique\n  /// Failed poster runs. The cron stops after a few, so one unreadable file cannot\n  /// occupy every run.\n  posterAttempts Int         @default(0)\n  createdAt      DateTime    @default(now())\n\n  room         Room             @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  items        InspectionItem[]\n  itemEvidence ItemEvidence[]\n\n  @@index([roomId])\n}\n\nenum RoomStatus {\n  /// Created by the inspector, nothing captured yet.\n  PENDING\n  CAPTURING\n  PROCESSING\n  /// Draft items exist, awaiting a human pass.\n  REVIEW\n  REVIEWED\n  FAILED\n}\n\nmodel Room {\n  id                  String     @id @default(cuid())\n  inspectionId        String\n  name                String\n  order               Int\n  status              RoomStatus @default(PENDING)\n  processingError     String?\n  processingAttemptId String?\n  processingStartedAt DateTime?\n  createdAt           DateTime   @default(now())\n  updatedAt           DateTime   @updatedAt\n\n  inspection Inspection       @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  captures   Capture[]\n  items      InspectionItem[]\n\n  @@index([inspectionId])\n}\n\nenum ItemCategory {\n  FIXTURE\n  APPLIANCE\n  FURNITURE\n  SURFACE\n  METER\n}\n\nenum ItemCondition {\n  NEW\n  GOOD\n  FAIR\n  POOR\n  DAMAGED\n}\n\nmodel InspectionItem {\n  id                 String        @id @default(cuid())\n  roomId             String\n  name               String\n  category           ItemCategory\n  condition          ItemCondition\n  quantity           Int           @default(1)\n  notes              String?\n  /// Make, model, and serial read verbatim off a photographed label or plate.\n  /// This is what makes an inventory line identify one specific object rather than\n  /// a category of object. That difference is what decides a deposit dispute.\n  identifier         String?\n  /// Meter reading, verbatim as spoken or read. Free text, because units vary.\n  meterReading       String?\n  /// The capture this item was read from, so the report can show its evidence.\n  sourceCaptureId    String?\n  /// Where in that capture the item is clearest. Video captures only.\n  sourceTimestampSec Int?\n  /// Model self-reported confidence, 0–1. Null once a human has taken ownership.\n  confidence         Float?\n  editedByHuman      Boolean       @default(false)\n  /// A durable property asset selected by a human. Identifier similarity may be\n  /// suggested in UI, but model output never links assets automatically.\n  propertyAssetId    String?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  room          Room           @relation(fields: [roomId], references: [id], onDelete: Cascade)\n  sourceCapture Capture?       @relation(fields: [sourceCaptureId], references: [id], onDelete: SetNull)\n  propertyAsset PropertyAsset? @relation(fields: [propertyAssetId], references: [id], onDelete: SetNull)\n  evidence      ItemEvidence[]\n\n  findingsAsSubject  Finding[] @relation(\"FindingItem\")\n  findingsAsBaseline Finding[] @relation(\"FindingBaselineItem\")\n\n  @@index([roomId])\n  @@index([propertyAssetId])\n}\n\n/// A human-curated link from an inventory line to one or more original room captures.\n/// Notes and photo marks remain on Capture, so the same evidence is never copied or\n/// rewritten when it is attached to several items.\nmodel ItemEvidence {\n  itemId    String\n  captureId String\n  createdAt DateTime @default(now())\n\n  item    InspectionItem @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  capture Capture        @relation(fields: [captureId], references: [id], onDelete: Cascade)\n\n  @@id([itemId, captureId])\n  @@index([captureId])\n}\n\n// ---------------------------------------------------------------------------\n// M5: longitudinal property maintenance\n// ---------------------------------------------------------------------------\n\nenum PropertyAssetCategory {\n  APPLIANCE\n  FIXTURE\n  FURNITURE\n  SURFACE\n  SYSTEM\n  OTHER\n}\n\nmodel PropertyAsset {\n  id         String                @id @default(cuid())\n  propertyId String\n  name       String\n  category   PropertyAssetCategory\n  roomLabel  String?\n  identifier String?\n  active     Boolean               @default(true)\n  createdAt  DateTime              @default(now())\n  updatedAt  DateTime              @updatedAt\n\n  property         Property          @relation(fields: [propertyId], references: [id], onDelete: Cascade)\n  inspectionItems  InspectionItem[]\n  maintenanceCases MaintenanceCase[]\n\n  @@index([propertyId, active])\n  @@index([propertyId, identifier])\n}\n\nenum MaintenanceCategory {\n  APPLIANCE\n  PLUMBING\n  LOCKSMITH\n  ELECTRICAL\n  AIR_CONDITIONING\n  STRUCTURAL\n  PEST\n  OTHER\n}\n\nenum MaintenancePriority {\n  ROUTINE\n  URGENT\n  SAFETY_EMERGENCY\n}\n\nenum MaintenanceStatus {\n  REPORTED\n  ACKNOWLEDGED\n  SCHEDULED\n  AWAITING_CONFIRMATION\n  RESOLVED\n  CLOSED_NO_ACTION\n}\n\nmodel MaintenanceCase {\n  id               String              @id @default(cuid())\n  clientId         String?             @unique\n  tenancyId        String\n  propertyAssetId  String?\n  reportedById     String\n  category         MaintenanceCategory\n  priority         MaintenancePriority @default(ROUTINE)\n  title            String\n  description      String\n  status           MaintenanceStatus   @default(REPORTED)\n  resolutionReason String?\n  acknowledgedAt   DateTime?\n  resolvedAt       DateTime?\n  createdAt        DateTime            @default(now())\n  updatedAt        DateTime            @updatedAt\n\n  tenancy                 Tenancy                  @relation(fields: [tenancyId], references: [id], onDelete: Cascade)\n  propertyAsset           PropertyAsset?           @relation(fields: [propertyAssetId], references: [id], onDelete: SetNull)\n  reportedBy              Stakeholder              @relation(\"MaintenanceReporter\", fields: [reportedById], references: [id])\n  events                  MaintenanceEvent[]\n  visits                  MaintenanceVisit[]\n  evidence                MaintenanceEvidence[]\n  findings                Finding[]\n  responsibilityProposals ResponsibilityProposal[]\n\n  @@index([tenancyId, status, createdAt])\n  @@index([propertyAssetId, createdAt])\n}\n\nenum MaintenanceEventKind {\n  REPORTED\n  COMMENT\n  STATUS_CHANGED\n  VISIT_RECORDED\n  VERIFICATION\n  REOPENED\n  RESPONSIBILITY_PROPOSED\n  RESPONSIBILITY_ACCEPTED\n  RESPONSIBILITY_REJECTED\n  RESPONSIBILITY_WITHDRAWN\n}\n\nmodel MaintenanceEvent {\n  id        String               @id @default(cuid())\n  caseId    String\n  actorId   String?\n  kind      MaintenanceEventKind\n  body      String?\n  metadata  Json?\n  createdAt DateTime             @default(now())\n\n  maintenanceCase MaintenanceCase @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  actor           Stakeholder?    @relation(fields: [actorId], references: [id], onDelete: SetNull)\n\n  @@index([caseId, createdAt])\n}\n\nmodel MaintenanceVisit {\n  id          String    @id @default(cuid())\n  caseId      String\n  providerId  String?\n  scheduledAt DateTime?\n  completedAt DateTime?\n  notes       String?\n  cost        Decimal?  @db.Decimal(10, 2)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  maintenanceCase MaintenanceCase          @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  provider        ServiceProvider?         @relation(fields: [providerId], references: [id], onDelete: SetNull)\n  evidence        MaintenanceEvidence[]\n  verification    MaintenanceVerification?\n\n  @@index([caseId, completedAt])\n}\n\nenum MaintenanceEvidencePurpose {\n  BEFORE\n  AFTER\n  RECEIPT\n}\n\nmodel MaintenanceEvidence {\n  id           String                     @id @default(cuid())\n  clientId     String                     @unique\n  caseId       String\n  visitId      String?\n  uploadedById String\n  purpose      MaintenanceEvidencePurpose\n  storagePath  String                     @unique\n  mimeType     String\n  sizeBytes    Int\n  note         String?\n  createdAt    DateTime                   @default(now())\n\n  maintenanceCase MaintenanceCase   @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  visit           MaintenanceVisit? @relation(fields: [visitId], references: [id], onDelete: SetNull)\n  uploadedBy      Stakeholder       @relation(fields: [uploadedById], references: [id])\n\n  @@index([caseId, createdAt])\n  @@index([visitId])\n}\n\nenum MaintenanceVerificationOutcome {\n  FIXED\n  NOT_FIXED\n}\n\nmodel MaintenanceVerification {\n  id           String                         @id @default(cuid())\n  visitId      String                         @unique\n  verifiedById String\n  outcome      MaintenanceVerificationOutcome\n  note         String?\n  createdAt    DateTime                       @default(now())\n\n  visit      MaintenanceVisit @relation(fields: [visitId], references: [id], onDelete: Cascade)\n  verifiedBy Stakeholder      @relation(fields: [verifiedById], references: [id])\n}\n\nenum RepairParty {\n  LANDLORD\n  TENANT\n}\n\nenum CostPayer {\n  LANDLORD\n  TENANT\n  SHARED\n}\n\nenum ResponsibilityBasis {\n  MINOR_REPAIR_CLAUSE\n  TENANT_CAUSED\n  FAIR_WEAR\n  LANDLORD_OBLIGATION\n  OTHER\n}\n\nenum ProposalStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  WITHDRAWN\n  SUPERSEDED\n}\n\n/// Who arranges a repair and who pays for it, as one side proposes and the other\n/// answers. Append-only: changing an agreement is a new proposal, never an edit.\n/// At most one PENDING and one ACCEPTED per case, enforced by partial unique indexes\n/// in the migration because Prisma cannot express them.\nmodel ResponsibilityProposal {\n  id            String              @id @default(cuid())\n  caseId        String\n  proposedById  String\n  arrangedBy    RepairParty\n  payer         CostPayer\n  /// Required when payer is SHARED: the tenant pays up to this, the landlord the rest.\n  tenantCap     Decimal?            @db.Decimal(10, 2)\n  basis         ResponsibilityBasis\n  reason        String\n  /// Free text such as \"Clause 5(c)\" until tenancy agreements are extracted.\n  clauseRef     String?\n  status        ProposalStatus      @default(PENDING)\n  respondedById String?\n  respondedAt   DateTime?\n  responseNote  String?\n  createdAt     DateTime            @default(now())\n\n  maintenanceCase MaintenanceCase @relation(fields: [caseId], references: [id], onDelete: Cascade)\n  proposedBy      Stakeholder     @relation(\"ResponsibilityProposer\", fields: [proposedById], references: [id])\n  respondedBy     Stakeholder?    @relation(\"ResponsibilityResponder\", fields: [respondedById], references: [id])\n\n  @@index([caseId, createdAt])\n}\n\nenum ServiceProviderCategory {\n  PLUMBING\n  LOCKSMITH\n}\n\nmodel ServiceProvider {\n  id             String                  @id @default(cuid())\n  name           String\n  category       ServiceProviderCategory\n  phone          String\n  whatsapp       String?\n  serviceAreas   String[]\n  hours          String?\n  lastVerifiedAt DateTime\n  active         Boolean                 @default(true)\n  createdAt      DateTime                @default(now())\n  updatedAt      DateTime                @updatedAt\n\n  visits MaintenanceVisit[]\n\n  @@unique([category, phone])\n  @@index([category, active])\n}\n\nenum NotificationKind {\n  MAINTENANCE_REPORTED\n  MAINTENANCE_STATUS\n  MAINTENANCE_VISIT\n  MAINTENANCE_VERIFICATION\n  MAINTENANCE_RESPONSIBILITY\n  REPEAT_REPAIR\n}\n\nenum DevicePlatform {\n  ANDROID\n  IOS\n}\n\nmodel DeviceInstallation {\n  id            String         @id @default(cuid())\n  stakeholderId String\n  token         String         @unique\n  platform      DevicePlatform\n  lastSeenAt    DateTime       @default(now())\n  disabledAt    DateTime?\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n\n  stakeholder Stakeholder                @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n  deliveries  NotificationPushDelivery[]\n\n  @@index([stakeholderId, disabledAt, lastSeenAt])\n}\n\nmodel Notification {\n  id             String           @id @default(cuid())\n  recipientId    String\n  kind           NotificationKind\n  title          String\n  body           String\n  href           String?\n  dedupeKey      String?          @unique\n  readAt         DateTime?\n  emailTo        String?\n  emailAttempts  Int              @default(0)\n  emailSentAt    DateTime?\n  emailError     String?\n  pushExpandedAt DateTime?\n  createdAt      DateTime         @default(now())\n\n  recipient      Stakeholder                @relation(fields: [recipientId], references: [id], onDelete: Cascade)\n  pushDeliveries NotificationPushDelivery[]\n\n  @@index([recipientId, readAt, createdAt])\n  @@index([emailSentAt, emailAttempts, createdAt])\n  @@index([pushExpandedAt, createdAt])\n}\n\nmodel NotificationPushDelivery {\n  id             String    @id @default(cuid())\n  notificationId String\n  installationId String\n  attempts       Int       @default(0)\n  claimedAt      DateTime?\n  sentAt         DateTime?\n  error          String?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  notification Notification       @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n  installation DeviceInstallation @relation(fields: [installationId], references: [id], onDelete: Cascade)\n\n  @@unique([notificationId, installationId])\n  @@index([sentAt, attempts, createdAt])\n}\n\nenum ChangeType {\n  UNCHANGED\n  WEAR\n  DAMAGE\n  MISSING\n  IMPROVED\n}\n\nenum Verdict {\n  TENANT_LIABLE\n  FAIR_WEAR\n  DISPUTED\n  UNDECIDED\n}\n\n/// Check-out only. The dispute moment, drafted by the model and owned by a human.\nmodel Finding {\n  id                String     @id @default(cuid())\n  inspectionId      String\n  itemId            String?\n  baselineItemId    String?\n  /// Human-selected maintenance history to preserve with a published assessment.\n  maintenanceCaseId String?\n  changeType        ChangeType\n  verdict           Verdict    @default(UNDECIDED)\n  rationale         String\n  estimatedCost     Decimal?   @db.Decimal(10, 2)\n  confidence        Float?\n  editedByHuman     Boolean    @default(false)\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  inspection      Inspection       @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  item            InspectionItem?  @relation(\"FindingItem\", fields: [itemId], references: [id], onDelete: SetNull)\n  baselineItem    InspectionItem?  @relation(\"FindingBaselineItem\", fields: [baselineItemId], references: [id], onDelete: SetNull)\n  maintenanceCase MaintenanceCase? @relation(fields: [maintenanceCaseId], references: [id], onDelete: SetNull)\n\n  @@index([inspectionId])\n  @@index([maintenanceCaseId])\n}\n\nmodel Signature {\n  id            String   @id @default(cuid())\n  inspectionId  String\n  stakeholderId String\n  signedAt      DateTime @default(now())\n  ipAddress     String?\n  /// data: URL of the drawn signature.\n  imageData     String\n\n  inspection  Inspection  @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n  stakeholder Stakeholder @relation(fields: [stakeholderId], references: [id])\n\n  @@unique([inspectionId, stakeholderId])\n}\n\n/// A human-published, immutable assessment. The signed inventory has its own lifecycle.\nmodel AssessmentVersion {\n  id            String   @id @default(cuid())\n  inspectionId  String\n  version       Int\n  snapshot      Json\n  contentHash   String\n  publishedAt   DateTime @default(now())\n  publishedById String\n\n  inspection Inspection @relation(fields: [inspectionId], references: [id], onDelete: Cascade)\n\n  @@unique([inspectionId, version])\n  @@index([inspectionId, publishedAt])\n}\n\nenum DeletionRequestStatus {\n  REQUESTED\n  PROCESSING\n  COMPLETED\n}\n\n/// In-app requests are fulfilled by an operator under the approved retention policy.\nmodel AccountDeletionRequest {\n  id                      String                @id @default(cuid())\n  stakeholderId           String                @unique\n  status                  DeletionRequestStatus @default(REQUESTED)\n  requestedAt             DateTime              @default(now())\n  dueAt                   DateTime\n  completedAt             DateTime?\n  notificationSentAt      DateTime?\n  processingPolicyVersion String?\n  fulfilledUnderPolicy    String?\n  email                   String?\n\n  stakeholder   Stakeholder                   @relation(fields: [stakeholderId], references: [id])\n  storagePurges AccountDeletionStoragePurge[]\n\n  @@index([status, dueAt])\n  @@index([stakeholderId, requestedAt])\n}\n\n/// A durable prefix manifest for media belonging to an erased draft room. Signed\n/// upload URLs can remain valid for two hours after the room row is deleted; cleanup\n/// only completes after that window and a verified empty Storage listing.\nmodel AccountDeletionStoragePurge {\n  id          String    @id @default(cuid())\n  requestId   String\n  roomId      String    @unique\n  readyAt     DateTime\n  completedAt DateTime?\n\n  request AccountDeletionRequest @relation(fields: [requestId], references: [id], onDelete: Cascade)\n\n  @@index([requestId, completedAt])\n}\n\n/// Tombstone for a capture or room removed from the working report. The DB row may\n/// disappear before a still-valid signed upload URL expires, so Storage removal is\n/// delayed and retried independently of the request that deleted the row.\nmodel StoragePurge {\n  id          String    @id @default(cuid())\n  path        String    @unique\n  isPrefix    Boolean\n  readyAt     DateTime\n  completedAt DateTime?\n  createdAt   DateTime  @default(now())\n\n  @@index([completedAt, readyAt])\n}\n\nenum ErrorSource {\n  SERVER\n  WEB\n  ANDROID\n  IOS\n}\n\n/// One error, as it happened, from the server, an agent's browser, or the app. Grouped on read by\n/// `fingerprint`, a hash of where it came from and what it said with ids and numbers\n/// normalized out, so the same bug on two inspections is one problem rather than two.\n/// `notifiedAt` is stamped by the alert cron, which emails a fingerprint only the first\n/// time it is seen. Kept for 90 days, as the privacy policy says.\nmodel ErrorEvent {\n  /// A browser report carries its own UUID, so a retried batch cannot record twice.\n  id            String      @id @default(uuid())\n  source        ErrorSource\n  /// Where it was caught: render, action, route or api on the server; boundary, window\n  /// or rejection in the browser; flutter, platform or caught in the app.\n  context       String\n  name          String\n  message       String\n  stack         String?\n  /// React's digest for a server error. The browser shows it as the error's reference,\n  /// so it is how an agent's screenshot is matched to the stack.\n  digest        String?\n  path          String?\n  release       String?\n  userAgent     String?\n  fingerprint   String\n  stakeholderId String?\n  occurredAt    DateTime\n  createdAt     DateTime    @default(now())\n  notifiedAt    DateTime?\n\n  stakeholder Stakeholder? @relation(fields: [stakeholderId], references: [id], onDelete: Cascade)\n\n  @@index([fingerprint])\n  @@index([notifiedAt])\n  @@index([createdAt])\n  @@index([stakeholderId])\n}\n"
}

